NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Revelation of John'

CHAPTERS = {
    1: {
        1: 'Die Offenbarung von Jesus Christus, welche Gott Ihm gab, Seinen Knechten zu zeigen, was in Bälde geschehen soll, und Er deutete es, da Er durch Seinen Engel an Seinen Knecht Johannes entsandte.',
        2: 'Welcher bezeugte das Wort Gottes und das Zeugnis von Jesus Christus, was er alles gesehen.',
        3: 'Selig, wer da liest, und die da hören die Worte der Weissagung, und was in ihr geschrieben ist, halten; denn die Zeit ist nahe.',
        4: 'Johannes an die sieben Gemeinden in Asien: Gnade sei euch und Friede von Ihm, Der da ist, und Der da war, und Der da kommt, und von den sieben Geistern, die vor Seinem Throne sind.',
        5: 'Und von Jesus Christus, Der da ist der treue Zeuge, der Erstgeborene aus den Toten und der Oberste der Könige der Erde, Der uns liebt und uns in Seinem Blute von unseren Sünden gewaschen.',
        6: 'Und uns zu Königen und zu Priestern Gott und Seinem Vater gemacht. Ihm sei die Herrlichkeit und Macht in die Zeitläufe der Zeitläufe! Amen.',
        7: 'Siehe, Er kommt mit den Wolken und sehen wird Ihn jegliches Auge, auch die Ihn durchstochen haben, und jammern werden ob Ihm alle Stämme der Erde. Ja, Amen.',
        8: 'Ich bin das Alpha und das Omega, der Anfang und das Ende, spricht der Herr, Der da ist, und Der da war, und Der da kommt, der Allmächtige.',
        9: 'Ich, Johannes, der auch euer Bruder und Teilhaber an der Trübsal und am Reich und an der geduldigen Erwartung von Jesus Christus ist, war auf der Insel, die Patmos heißt, um des Wortes Gottes willen, und des Zeugnisses von Jesus Christus.',
        10: 'Ich war im Geist am Tage des Herrn, und hörte hinter mir eine große Stimme, als eine Posaune.',
        11: 'Die sprach: Ich bin das Alpha und das Omega, der Erste und der Letzte, und was Du siehst, schreibe in ein Buch und sende es den Gemeinden in Asien gen Ephesus und gen Smyrna und gen Pergamus und gen Thyatira und gen Sardes und gen Philadelphia und gen Laodikia.',
        12: 'Und ich wandte mich um, zu sehen die Stimme, die mit mir redete, und da ich mich umwandte, sah ich sieben goldene Leuchter,',
        13: 'Und inmitten der sieben Leuchter Einen, Der dem Menschensohne ähnlich war, mit einem Talar angetan, und um die Brust mit einem goldenen Gürtel umgürtet.',
        14: 'Sein Haupt aber und die Haare weiß, wie weiße Wolle, wie Schnee, und Seine Augen wie eine Feuerflamme,',
        15: 'Und Seine Füße ähnlich dem Glüherz, wie im Ofen geglüht, und Seine Stimme, wie die Stimme vieler Wasser.',
        16: 'Und Er hatte in Seiner rechten Hand sieben Sterne, und aus Seinem Munde ging aus ein scharfes, zweischneidiges Schwert, und Sein Angesicht, wie die Sonne leuchtet in ihrer Kraft.',
        17: 'Und da ich Ihn sah, fiel ich wie tot zu Seinen Füßen; und Er legte Seine rechte Hand auf mich und sprach zu mir: Fürchte dich nicht. Ich bin der Erste und der Letzte,',
        18: 'Und der Lebendige. Und Ich ward tot und siehe, Ich bin lebendig in die Zeitläufe der Zeitläufe. Amen. Und Ich habe die Schlüssel der Hölle und des Todes.',
        19: 'Schreibe, was du gesehen hast, und was da ist, und was zukünftig nach diesem geschehen wird.',
        20: 'Das Geheimnis der sieben Sterne, die du in Meiner Rechten sahst, und die sieben goldenen Leuchter: Die sieben Sterne sind Engel der sieben Gemeinden und die sieben Leuchter, die du gesehen hast, sind die sieben Gemeinden.',
    },
    2: {
        1: 'Dem Engel der Gemeinde in Ephesus schreibe: Das sagt, Der die sieben Sterne in Seiner Rechten festhält und in der Mitte der sieben goldenen Leuchter wandelt:',
        2: 'Ich kenne deine Werke und dein Mühen und deine Geduld, und daß du die Bösen nicht tragen kannst und daß du hast geprüft die, so da sagen, sie seien Apostel, und es nicht sind, und hast sie als Lügner erfunden;',
        3: 'Und hast getragen und hast Geduld und hast um Meines Namens willen dich abgemüht und bist nicht müde geworden.',
        4: 'Aber Ich habe wider dich, daß du deine erste Liebe verlassen hast.',
        5: 'Bedenke denn, wovon du abgefallen bist; und tue Buße und tue die ersten Werke; wo aber nicht, so komme Ich schnell über dich und rücke deinen Leuchter von seinem Ort, wenn du nicht Buße tust.',
        6: 'Doch hast du dies, daß du die Werke der Nikolaiten hassest, welche auch Ich hasse.',
        7: 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt: Dem Überwinder will Ich zu essen geben vom Baume des Lebens, der in der Mitte des Paradieses Gottes ist.',
        8: 'Und dem Engel der Gemeinde in Smyrna schreibe: Das sagt der Erste und der Letzte, Der tot ward und lebt:',
        9: 'Ich weiß deine Werke und die Trübsal und die Armut und die Lästerung derer, die da sagen, sie seien Juden, und sind keine, sondern eine Synagoge des Satans.',
        10: 'Fürchte dich vor deren keinem, das du leiden wirst. Siehe, der Teufel wird etliche von euch ins Gefängnis werfen, auf daß ihr versucht werdet; und ihr werdet Trübsal haben zehn Tage. Sei getreu bis zum Tod, und Ich will dir die Krone des Lebens geben.',
        11: 'Wer ein Ohr hat, der höre, was der Geist zu den Gemeinden sagt: Der Überwinder soll nicht geschädigt werden vom zweiten Tod.',
        12: 'Und dem Engel der Gemeinde in Pergamus schreibe: Das sagt, Der das scharfe, zweischneidige Schwert hat.',
        13: 'Ich weiß deine Werke, und wo du wohnst, wo des Satans Thron ist; und du hältst fest an Meinem Namen und hast nicht verleugnet den Glauben an Mich auch in den Tagen, wo Antipas, Mein treuer Zeuge, bei euch, da Satan wohnt, getötet worden.',
        14: 'Aber Ich habe einiges wider dich: daß du daselbst hast, die an der Lehre Bileams festhalten, der den Balak lehrte, vor die Söhne Israels ein Ärgernis zu legen, daß sie Götzenopfer aßen und Buhlerei trieben.',
        15: 'So hast auch du solche, die an der Lehre der Nikolaiten festhalten, was Ich hasse.',
        16: 'Tue Buße, sonst aber komme Ich schnell zu dir, und streite wider sie mit dem Schwert Meines Mundes.',
        17: 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt: Dem Überwinder will Ich von dem verborgenen Manna zu essen geben und will ihm einen weißen Stein geben, und auf dem Stein einen neuen Namen geschrieben, den niemand erkennt, als der ihn empfängt.',
        18: 'Und dem Engel der Gemeinde in Thyatira schreibe: Das sagt der Sohn Gottes, Der Augen hat wie eine Feuerflamme, und Füße ähnlich dem Glüherz.',
        19: 'Ich weiß deine Werke, und deine Liebe, und deine Dienstleistung, und deinen Glauben, und deine Geduld, und deine Werke, und daß der letzten mehr sind als der ersten.',
        20: 'Aber Ich habe einiges wider dich, daß du das Weib Jesabel, die da sagt, sie sei eine Prophetin, Meine Knechte lehren und zur Buhlerei und zum Essen von Götzenopfern irreführen lässest.',
        21: 'Und Ich habe ihr Zeit gegeben, für ihre Buhlerei Buße zu tun, und sie hat nicht Buße getan.',
        22: 'Siehe, Ich werfe sie in ein Bett, und in große Trübsal, die mit ihr die Ehe brechen, wenn sie nicht Buße tun von ihren Werken.',
        23: 'Und ihre Kinder will Ich mit dem Tode töten; und erkennen sollen alle Gemeinden, daß Ich es bin, Der Nieren und Herzen erforscht, und einem jeden von euch nach euren Werken geben werde.',
        24: 'Euch aber sage Ich und den übrigen in Thyatira, so viele als diese Lehre nicht haben, und welche die Tiefen des Satanas, wie sie es nennen, nicht erkannt haben, Ich will keine andere Last auf euch werfen.',
        25: 'Doch was ihr habt, an dem haltet fest, bis daß Ich komme.',
        26: 'Wer überwindet und hält Meine Werke bis ans Ende, dem will Ich Gewalt über die Völkerschaften geben.',
        27: 'Und mit eisernem Stabe soll er sie weiden, und wie Töpfergeschirr sollen sie zerschlagen werden,',
        28: 'Wie auch Ich von Meinem Vater empfangen habe; und Ich werde ihm geben den Morgenstern.',
        29: 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.',
    },
    3: {
        1: 'Und dem Engel der Gemeinde in Sardes schreibe: Das sagt, Der die sieben Geister Gottes und die sieben Sterne hat: Ich weiß deine Werke, daß du den Namen hast, daß du lebst, und bist tot.',
        2: 'Sei wachsam und mache fest, was übrig ist und sterben will; denn Ich habe deine Werke nicht voll gefunden vor Gott.',
        3: 'Gedenke denn, wie du es empfangen und gehört hast, und halte es und tue Buße. Wenn du nun nicht wachest, so werde Ich über dich kommen, wie ein Dieb, und du wirst nicht erkennen, zu welcher Stunde Ich werde über dich kommen.',
        4: 'Du hast auch in Sardes wenige Namen, die ihre Kleider nicht befleckten, und sie werden in weißen Kleidern mit Mir wandeln, weil sie es wert sind.',
        5: 'Wer überwindet, soll mit weißen Kleidern umkleidet werden; und Ich werde seinen Namen nicht auswischen aus dem Buche des Lebens, und werde seinen Namen bekennen vor Meinem Vater und vor Seinen Engeln.',
        6: 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.',
        7: 'Und dem Engel der Gemeinde in Philadelphia schreibe: Das sagt der Heilige, der Wahrhaftige, Der den Schlüssel Davids hat, Der auftut, und niemand verschließt, und verschließt, und niemand tut auf.',
        8: 'Ich weiß deine Werke. Siehe, Ich habe vor dir eine geöffnete Tür gegeben, und niemand kann sie verschließen, weil du eine kleine Kraft hast, und hast Mein Wort gehalten und Meinen Namen nicht verleugnet.',
        9: 'Siehe, Ich will aus Satans Synagoge geben, die sagen, sie seien Juden, und sind es nicht, sondern lügen. Siehe, Ich will machen, daß sie kommen und vor deinen Füßen anbeten und erkennen, daß Ich dich geliebt habe.',
        10: 'Weil du das Wort Meiner Geduld behalten hast, will auch Ich dich behalten vor der Stunde der Versuchung, die über den ganzen Erdkreis kommen wird, zu versuchen, die auf Erden wohnen.',
        11: 'Siehe, Ich komme schnell. Halte fest, was du hast, auf daß niemand deine Krone nehme.',
        12: 'Den Überwinder will Ich zur Säule in Meines Gottes Tempel machen, und er soll nicht mehr hinausgehen, und Ich will auf ihn schreiben den Namen Meines Gottes und den Namen der Stadt Meines Gottes, des neuen Jerusalem, das aus dem Himmel von Meinem Gotte herabsteigt, und Meinen neuen Namen.',
        13: 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt!',
        14: 'Und dem Engel der Gemeinde in Laodikia schreibe: Das sagt der Amen, der treue und wahrhaftige Zeuge, der Anfang der Schöpfung Gottes.',
        15: 'Ich weiß deine Werke, daß du weder kalt noch warm bist. Wärest du doch kalt oder warm.',
        16: 'So aber, da du lau bist, und weder kalt noch warm, will Ich dich ausspeien aus Meinem Munde.',
        17: 'Daß du sagst: Ich bin reich, und bin reich geworden, und bedarf nichts, und du weißt nicht, daß du elend und jämmerlich und arm und blind und nackend bist.',
        18: 'Ich rate dir, kaufe von Mir Gold, durch Feuer geläutert, auf daß du reich werdest, und weiße Kleider, auf daß du umkleidest werdest, und die Schande deiner Blöße nicht offenbar werde, und Augensalbe, deine Augen damit einzusalben, auf daß du sehen mögest.',
        19: 'Wen Ich lieb habe, den rüge und züchtige Ich. Beeifre dich denn und tue Buße.',
        20: 'Siehe, Ich stehe an der Tür und klopfe an. So jemand Meine Stimme hört und die Tür auftut, zu dem gehe Ich ein und halte Abendmahl mit ihm und er mit Mir.',
        21: 'Dem Überwinder will Ich geben, auf Meinem Thron mit Mir zu sitzen, wie Ich überwunden und mit Meinem Vater auf Seinem Thron gesessen bin.',
        22: 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.',
    },
    4: {
        1: 'Danach sah ich, und siehe, eine Tür hatte sich im Himmel aufgetan. Und die erste Stimme, die ich wie eine Posaune mit mir reden hörte, sagte: Steige hier herauf, und ich will dir zeigen, was nach diesem geschehen soll.',
        2: 'Und alsbald war ich im Geiste; und siehe! ein Thron war gestellt im Himmel, und auf dem Throne saß Einer.',
        3: 'Und Der da saß, war ähnlich im Ansehen wie der Stein Jaspis und Sarder, und rings um den Thron ein Farbenbogen, ähnlich einem Smaragd im Ansehen.',
        4: 'Und rings um den Thron vierundzwanzig Throne; und auf den Thronen sah ich sitzen die vierundzwanzig Ältesten; diese waren umkleidet mit weißen Kleidern und hatten goldene Kronen auf ihren Häuptern.',
        5: 'Und aus dem Thron gehen Blitze und Stimmen und Donner aus, und vor dem Throne brennen sieben Fackeln von Feuer, welche die sieben Geister Gottes sind.',
        6: 'Und vor dem Throne ein gläsern Meer, ähnlich dem Kristall. Und inmitten des Throns und rings um den Thron vier Tiere voller Augen vorn und hinten.',
        7: 'Und das erste Tier glich einem Löwen, und das zweite Tier glich einem Kalb, und das dritte Tier hatte das Angesicht wie ein Mensch, und das vierte Tier glich einem fliegenden Adler.',
        8: 'Und die vier Tiere hatten, jedes für sich, je sechs Flügel ringsum, und waren innen voller Augen und hatten keine Ruhe Tag und Nacht, und sagten: Heilig, heilig, heilig ist der Herr, Gott, der Allmächtige, Der da war und Der da ist und Der da kommt.',
        9: 'Und da die Tiere Herrlichkeit und Ehre und Danksagung gaben Dem, Der auf dem Throne sitzt, Der da lebt in die Zeitläufe der Zeitläufe,',
        10: 'Fielen die vierundzwanzig Ältesten vor dem auf dem Throne Sitzenden nieder und beteten an Ihn, Der in die Zeitläufe der Zeitläufe lebt, und warfen ihre Kronen vor den Thron und sprachen:',
        11: 'Herr, Du bist würdig, zu nehmen die Herrlichkeit und die Ehre und die Kraft, denn Du hast alle Dinge geschaffen, und durch Deinen Willen sind sie und wurden sie geschaffen.',
    },
    5: {
        1: 'Und ich sah in der Rechten Dessen, Der auf dem Throne saß, ein Buch, inwendig und auswendig beschrieben, versiegelt mit sieben Siegeln.',
        2: 'Und ich sah einen starken Engel mit großer Stimme ausrufen: Wer ist würdig, das Buch aufzutun und seine Siegel zu lösen?',
        3: 'Und niemand im Himmel, noch auf Erden, noch unter der Erde konnte das Buch auftun und hineinsehen.',
        4: 'Und ich weinte sehr, daß niemand würdig gefunden wurde, das Buch aufzutun und zu lesen, noch hineinzusehen.',
        5: 'Und einer von den Ältesten sprach zu mir: Weine nicht! Siehe, der Löwe, der da ist aus dem Stamme Juda, die Wurzel Davids, hat überwunden, das Buch aufzutun und seine sieben Siegel zu lösen!',
        6: 'Und ich sah, und siehe, inmitten des Throns und der vier Tiere und inmitten der Ältesten stand ein Lamm, als wäre es erschlagen, das hatte sieben Hörner und sieben Augen, welche sind die sieben Geister Gottes, ausgesandt in die ganze Erde.',
        7: 'Und es kam und nahm das Buch aus der Rechten Dessen, Der auf dem Throne saß.',
        8: 'Und da es das Buch nahm, fielen die vier Tiere und die vierundzwanzig Ältesten vor das Lamm. Sie hatten jeder Harfen und goldene Schalen voll Räucherwerks, welches sind die Gebete der Heiligen.',
        9: 'Und singen ein neues Lied und sagen: Du bist würdig, das Buch zu nehmen und seine Siegel aufzutun; denn du wardst erschlagen und hast uns für Gott erkauft mit Deinem Blute aus allerlei Stamm und Zunge und Volk und Völkerschaft.',
        10: 'Und uns unsrem Gotte zu Königen und Priestern gemacht, und regieren werden wir auf Erden.',
        11: 'Und ich sah, und hörte die Stimme vieler Engel rings um den Thron und die Tiere und die Ältesten, und ihre Zahl war Myriaden von Myriaden und Tausende von Tausenden.',
        12: 'Und sie sagten mit großer Stimme: Würdig ist das Lamm, das erschlagene, zu nehmen die Kraft und Reichtum und Weisheit und Stärke und Ehre und Herrlichkeit und Segen.',
        13: 'Und alles Geschaffene, das da ist im Himmel und auf Erden und unter der Erde, und die im Meere sind, und alles, was in denselben ist, hörte ich sagen: Dem, Der auf dem Throne sitzt und dem Lamme sei der Segen und die Ehre und die Herrlichkeit und die Macht in die Zeitläufe der Zeitläufe.',
        14: 'Und die vier Tiere sprachen: Amen! Und die vierundzwanzig Ältesten fielen nieder und beteten an Ihn, Der da lebt in die Zeitläufe der Zeitläufe.',
    },
    6: {
        1: 'Und ich sah, wie das Lamm das erste der Siegel auftat, und hörte eines von den Tieren wie mit des Donners Stimme sagen: Komm und siehe!',
        2: 'Und ich sah, und siehe! ein weißes Pferd, und der darauf saß, hatte einen Bogen, und ihm ward eine Krone gegeben, und er zog aus als Überwinder, und um zu überwinden.',
        3: 'Und da es das zweite Siegel auftat, hörte ich das zweite Tier sagen: Komm und siehe!',
        4: 'Und es ging ein anderes, feuerrotes Pferd hervor, und dem darauf Sitzenden ward gegeben, den Frieden von der Erde zu nehmen, daß sie einander erschlugen; und es ward ihm ein großes Schwert gegeben.',
        5: 'Und da es das dritte Siegel auftat, hörte ich das dritte Tier sagen: Komm und siehe! Und ich sah, und siehe! ein schwarzes Pferd, und der darauf saß, hatte eine Waage in seiner Hand.',
        6: 'Und ich hörte eine Stimme inmitten der vier Tiere sagen: Ein Maß Weizen um einen Denar und drei Maß Gerste um einen Denar. Und das Öl und den Wein sollst du nicht schädigen.',
        7: 'Und da es das vierte Siegel auftat, hörte ich die Stimme des vierten Tieres sagen: Komm und siehe!',
        8: 'Und ich sah, und siehe! ein fahles Pferd, und der Name dessen, der darauf saß, war der Tod, und die Hölle folgte mit ihm nach. Und ihm ward Gewalt gegeben über den vierten Teil der Erde, zu töten durch das Schwert und durch Hunger und durch Tod und durch die wilden Tiere der Erde.',
        9: 'Und als es das fünfte Siegel auftat, sah ich unterhalb des Altars die Seelen derer, die um des Wortes Gottes und um des Zeugnisses willen, das sie hatten, erschlagen wurden.',
        10: 'Und sie schrien mit großer Stimme und sagten: Wie lange, o Herr, Du Heiliger und Wahrhaftiger, richtest Du nicht und rächst unser Blut an den Bewohnern der Erde?',
        11: 'Und es ward ihnen, einem jeglichen, weißes Gewand gegeben und ihnen gesagt, sie sollten noch eine kleine Zeit ruhen, bis auch vollzählig würden ihre Mitknechte, und ihre Brüder, die auch wie sie sollten getötet werden.',
        12: 'Und ich sah, da es das sechste Siegel auftat, und siehe! da ward ein großes Erdbeben, und die Sonne ward schwarz, wie ein härener Sack, und der Mond ward wie Blut,',
        13: 'Und die Sterne des Himmels fielen auf die Erde, wie der Feigenbaum seine unreifen Feigen abwirft, wenn er von einem großen Winde geschüttelt wird.',
        14: 'Und der Himmel entwich wie ein zusammengerolltes Buch, und jeder Berg und Insel wurden von ihren Orten gerückt.',
        15: 'Und die Könige der Erde und die Großen und die Reichen und die Kriegsobersten, und die Mächtigen, und jeder Knecht, und jeder Freie verbargen sich in die Höhlen und in die Felsen der Berge;',
        16: 'Und sprachen zu den Bergen und den Felsen: Fallet über uns, und verberget uns vor dem Angesichte Dessen, Der auf dem Throne sitzt, und vor dem Zorne des Lammes!',
        17: 'Denn gekommen ist der große Tag Seines Zornes. Und wer kann bestehen?',
    },
    7: {
        1: 'Und hierauf sah ich vier Engel auf den vier Ecken der Erde stehen, welche die vier Winde der Erde festhielten, auf daß kein Wind bliese über das Land oder über das Meer oder über irgendeinen Baum.',
        2: 'Und ich sah einen anderen Engel vom Aufgang der Sonne aufsteigen, der das Siegel des lebendigen Gottes hatte. Und er schrie mit großer Stimme den vier Engeln, denen gegeben war, das Land und das Meer zu schädigen;',
        3: 'Und er sprach: Schädigt nicht das Land, noch das Meer, noch die Bäume, bis wir die Knechte unseres Gottes auf ihren Stirnen besiegelt haben.',
        4: 'Und ich hörte die Zahl der Besiegelten: Hundertvierundvierzigtausend Besiegelte aus jedem Stamme der Söhne Israels.',
        5: 'Aus dem Stamme Judah zwölftausend Besiegelte; aus dem Stamme Ruben zwölftausend Besiegelte; aus dem Stamme Gad zwölftausend Besiegelte.',
        6: 'Aus dem Stamme Ascher zwölftausend Besiegelte; aus dem Stamme Naphthali zwölftausend Besiegelte; aus dem Stamme Menascheh zwölftausend Besiegelte;',
        7: 'Aus dem Stamme Simeon zwölftausend Besiegelte; aus dem Stamme Levi zwölftausend Besiegelte; aus dem Stamme Isaschar zwölftausend Besiegelte;',
        8: 'Aus dem Stamme Sebulon zwölftausend Besiegelte; aus dem Stamme Joseph zwölftausend Besiegelte; aus dem Stamme Benjamin zwölftausend Besiegelte.',
        9: 'Nach diesem sah ich, und siehe! eine große Menge, die niemand zählen konnte, aus allen Völkerschaften und Stämmen, und Völkern und Zungen vor dem Thron und vor dem Lamme stehen, mit weißen Gewändern umkleidet und Palmen in ihren Händen;',
        10: 'Und sie schrien mit großer Stimme und sprachen: Heil unserem Gott, Der da sitzt auf dem Thron, und dem Lamme!',
        11: 'Und alle Engel standen rings um den Thron und die Ältesten und die vier Tiere und fielen vor dem Throne auf ihr Angesicht und beteten Gott an,',
        12: 'Und sprachen: Amen, der Segen und die Herrlichkeit, und die Weisheit, und die Danksagung, und die Ehre, und die Kraft und die Stärke sei unserem Gott in die Zeitläufe der Zeitläufe. Amen.',
        13: 'Und einer von den Ältesten antwortete und sprach zu mir: Wer sind die, so mit weißen Gewändern umkleidet sind, und woher sind sie gekommen?',
        14: 'Und ich sprach zu ihm: Herr, du weißt es. Und er sprach zu mir: Die sind es, die aus der großen Trübsal kommen, und die ihre Gewänder ausgewaschen und ihre Gewänder im Blute des Lammes weiß gemacht haben.',
        15: 'Darum sind sie vor dem Throne Gottes und dienen Ihm Tag und Nacht in Seinem Tempel, und Der auf dem Throne sitzt, wird über ihnen wohnen.',
        16: 'Nicht mehr werden sie hungern, noch mehr dürsten, noch wird auf sie die Sonne, noch irgendeine Hitze fallen;',
        17: 'Denn das Lamm, das inmitten des Thrones ist, wird sie weiden, und zu lebendigen Quellen der Wasser leiten; und Gott wird alle Tränen von ihren Augen abwischen.',
    },
    8: {
        1: 'Und als es das siebente Siegel auftat, ward im Himmel eine Stille bei einer halben Stunde.',
        2: 'Und ich sah die sieben Engel, die vor Gott stehen, und es wurden ihnen sieben Posaunen gegeben.',
        3: 'Und ein anderer Engel kam und stellte sich an den Altar und hatte ein goldenes Räucherfaß. Und ihm wurde viel Räuchwerk gegeben, um es zu geben mit den Gebeten aller Heiligen auf dem goldenen Altar vor dem Throne.',
        4: 'Und es stieg auf der Rauch des Räuchwerks mit den Gebeten der Heiligen aus der Hand des Engels vor Gott.',
        5: 'Und der Engel nahm das Räuchfaß und füllte es aus dem Feuer des Altars und warf es auf die Erde; und es geschahen Stimmen und Donner und Blitze und Erdbeben.',
        6: 'Und die sieben Engel, welche die sieben Posaunen hatten, bereiteten sich zu posaunen.',
        7: 'Und der erste Engel posaunte, und es ward Hagel und Feuer mit Blut vermischt und wurde geworfen auf die Erde, und der dritte Teil der Bäume verbrannte, und alles grüne Gras verbrannte.',
        8: 'Und der zweite Engel posaunte, und es war, als würde ein großer Berg mit Feuer brennend ins Meer geworfen, und der dritte Teil des Meeres ward Blut.',
        9: 'Und der dritte Teil der Geschöpfe im Meer, die Seelen hatten, starb, und der dritte Teil der Schiffe wurde verdorben.',
        10: 'Und der dritte Engel posaunte, und es fiel ein großer Stern aus dem Himmel, brennend wie eine Fackel, und er fiel auf den dritten Teil der Flüsse und auf die Quellen der Wasser.',
        11: 'Und der Name des Sterns heißt Wermut, und der dritte Teil der Wasser ward Wermut, und viele Menschen starben von den Wassern, denn sie waren bitter geworden.',
        12: 'Und der vierte Engel posaunte, und geschlagen ward der dritte Teil der Sonne, und der dritte Teil des Mondes, und der dritte Teil der Sterne, so daß der dritte Teil derselben verfinstert ward, und der Tag sein drittes Teil nicht schien, und die Nacht desgleichen.',
        13: 'Und ich sah und hörte mitten am Himmel einen Engel fliegen und mit großer Stimme sagen: Wehe, wehe, wehe denen, die auf Erden wohnen, wegen der übrigen Stimmen der Posaunen der drei Engel, die posaunen werden.',
    },
    9: {
        1: 'Und der fünfte Engel posaunte, und ich sah einen Stern aus dem Himmel zur Erde fallen, und es ward ihm der Schlüssel des Brunnens des Abgrundes gegeben.',
        2: 'Und er tat den Brunnen des Abgrundes auf; und ein Rauch stieg auf aus dem Brunnen, wie der Rauch eines großen Ofens, und die Sonne und die Luft wurden verfinstert von dem Rauche des Brunnens.',
        3: 'Und aus dem Rauche kamen Heuschrekken hervor auf die Erde, und es ward ihnen Gewalt gegeben, wie die Skorpione der Erde Gewalt haben.',
        4: 'Und es ward ihnen gesagt, daß sie nicht sollten schädigen das Gras der Erde, noch irgend etwas Grünes, noch irgendwelchen Baum, sondern bloß die Menschen, die das Siegel Gottes nicht auf ihren Stirnen haben.',
        5: 'Und es ward ihnen gegeben, daß sie sie nicht töteten, sondern sie fünf Monate quälten, und die Qual war wie die Qual vom Skorpion, wenn er einen Menschen sticht.',
        6: 'Und in jenen Tagen werden die Menschen den Tod suchen und ihn nicht finden; und zu sterben begehren, und der Tod wird vor ihnen fliehen.',
        7: 'Und die Gestalten der Heuschrecken glichen zum Streit bereiteten Rossen, und auf ihren Häuptern hatten sie Kronen, dem Golde gleichend, und ihre Angesichter wie der Menschen Angesichter.',
        8: 'Und sie hatten Haare wie der Weiber Haare, und ihre Zähne waren wie der Löwen.',
        9: 'Und hatten Panzer, wie eiserne Panzer, und das Rauschen ihrer Flügel war wie das Rasseln von Streitwagen vieler Rosse, die in den Streit rennen.',
        10: 'Und Schwänze haben sie gleich den Skorpionen, und Stacheln waren an ihren Schwänzen, und hatten Gewalt, die Menschen fünf Monate zu schädigen.',
        11: 'Und hatten über sich einen König, den Engel des Abgrundes, dessen Namen im Hebräischen ist Abaddon, und im Griechischen hat er den Namen Apollyon.',
        12: 'Das eine Wehe ist vergangen. Siehe, es kommen noch zwei Wehe danach.',
        13: 'Und der sechste Engel posaunte; und ich hörte eine Stimme aus den vier Hörnern des goldenen Altars vor Gott,',
        14: 'Die sagte zu dem sechsten Engel, der die Posaune hatte: Löse die vier Engel, die an dem großen Fluß Euphrat gebunden sind!',
        15: 'Und die vier Engel wurden gelöst, welche auf Stunde und Tag und Monat und Jahr bereit waren, den dritten Teil der Men- schen zu töten.',
        16: 'Und die Zahl der Heerscharen der Reiterei waren zwei Myriaden von Myriaden. Und ich hörte ihre Zahl.',
        17: 'Und so sah ich die Rosse im Gesichte; und die auf ihnen saßen, hatten feuerrote, purpurblaue und schwefelfarbige Panzer; und die Häupter der Rosse waren wie der Löwen Häupter; und aus ihrem Munde ging aus Feuer, Rauch und Schwefel.',
        18: 'Und durch diese drei wurde das Drittel der Menschen getötet; durch das Feuer und durch den Rauch und durch den Schwefel, so aus ihrem Munde ausging.',
        19: 'Denn ihre Gewalt ist in ihrem Munde. Denn ihre Schwänze sind gleich Schlangen und haben Häupter; und mit diesen schädigen sie.',
        20: 'Und die übrigen von den Menschen, die durch diese Plagen nicht getötet wurden, noch Buße taten für die Werke ihrer Hände, so daß sie nicht anbeteten die Dämonen, und die goldenen und die silbernen, und die ehernen und die steinernen und die hölzernen Götzen, die weder sehen, noch hören, noch wandeln können.',
        21: 'Und taten nicht Buße für ihre Morde, noch für ihre Zaubereien, noch für ihre Buhlerei, noch für ihre Diebereien.',
    },
    10: {
        1: 'Und ich sah einen anderen starken Engel aus dem Himmel herabsteigen, mit einer Wolke umkleidet, und ein Farbenbogen über seinem Haupt, und sein Angesicht wie die Sonne, und seine Füße wie Feuersäulen.',
        2: 'Und in seiner Hand hatte er ein Büchlein aufgetan und setzte seinen rechten Fuß auf das Meer, den linken aber auf das Land.',
        3: 'Und er schrie mit großer Stimme, wie ein Löwe brüllt. Und da er schrie, redeten die sieben Donner ihre Stimmen.',
        4: 'Und als die sieben Donner ihre Stimme geredet hatten, wollte ich schreiben; und ich hörte eine Stimme aus dem Himmel zu mir sagen: Versiegle, was die sieben Donner geredet haben, und schreibe dasselbige nicht!',
        5: 'Und der Engel, den ich auf dem Meere und auf dem Lande stehen sah, hob auf seine Hand gen Himmel,',
        6: 'Und schwur bei Dem, Der da lebt in die Zeitläufe der Zeitläufe, Der den Himmel und was darinnen ist, und die Erde und was darin ist, und das Meer und was darin ist, geschaffen hat, daß keine Zeit mehr sein soll;',
        7: 'Sondern in den Tagen der Stimme des siebenten Engels, wann er posaunen wird, wird auch vollendet sein das Geheimnis Gottes, wie Er Seinen Knechten, den Propheten, verkündigt hat.',
        8: 'Und die Stimme, die ich aus dem Himmel gehört, redete abermals mit mir und sprach: Gehe hin, nimm das Büchlein, aufgetan in der Hand des Engels, der auf dem Meer und auf dem Lande steht.',
        9: 'Und ich ging hin zu dem Engel und sagte zu ihm: Gib mir das Büchlein, und er spricht zu mir: Nimm, iß es auf. Und deinen Leib wird es bitter machen, aber in deinem Munde süß sein wie Honig.',
        10: 'Und ich nahm das Büchlein aus der Hand des Engels und aß es auf; und in meinem Munde war es süß, wie Honig; und da ich es gegessen hatte, ward mein Leib bitter.',
        11: 'Und er spricht zu mir: Du mußt abermals weissagen über Völker und Völkerschaften und Zungen und viele Könige.',
    },
    11: {
        1: 'Und mir ward ein Rohr gegeben gleich einem Stabe, und gesagt: Mache dich auf, und miß den Tempel Gottes und den Altar und die darin anbeten.',
        2: 'Und den Vorhof, der außerhalb des Tempels ist, wirf hinaus und miß ihn nicht, weil er den Heiden gegeben ist; und sie werden die heilige Stadt zertreten zweiundvierzig Monate.',
        3: 'Und Meinen zwei Zeugen will Ich es geben, daß sie, mit Säcken umkleidet, tausendzweihundertsechzig Tage weissagen.',
        4: 'Dies sind die zwei Ölbäume und die zwei Leuchter, die vor dem Gott der Erde stehen.',
        5: 'Und wenn einer sie will schädigen, so geht Feuer aus ihrem Munde aus und verzehrt ihre Feinde; und wenn jemand sie will schädigen, so muß er also getötet werden.',
        6: 'Diese haben Gewalt, den Himmel zu verschließen, daß in den Tagen ihrer Weissagung der Schauer nicht regne; und haben Gewalt über die Wasser, sie in Blut umzuwandeln, und die Erde zu schlagen mit allerlei Plage, so oft sie nur wollen.',
        7: 'Und wenn sie ihr Zeugnis vollendet haben, wird das Tier, das aus dem Abgrund aufsteigt, Krieg mit ihnen führen und sie überwinden und sie töten.',
        8: 'Und ihre Leichen werden sein auf der Straße der großen Stadt, die geistig Sodom und Ägypten heißt, wo auch unser Herr gekreuzigt worden ist.',
        9: 'Und von den Völkern und Stämmen und Zungen und Völkerschaften werden welche deren Leichen drei und einen halben Tag sehen, und werden ihre Leichen nicht in die Grüfte legen lassen.',
        10: 'Und die auf Erden wohnen, werden sich über sie freuen und fröhlich sein und einander Geschenke schicken, weil diese zwei Propheten quälten, die auf Erden wohnen.',
        11: 'Und nach den drei und einen halben Tag kam der Geist des Lebens aus Gott in sie hinein, und sie standen auf ihre Füße, und große Furcht fiel auf die, so es schauten.',
        12: 'Und sie hörten eine große Stimme aus dem Himmel ihnen sagen: Steiget hier herauf. Und sie stiegen auf in den Himmel in der Wolke, und ihre Feinde schauten sie.',
        13: 'Und zur selben Stunde ward ein großes Erdbeben, und der zehnte Teil der Stadt fiel, und wurden getötet in dem Erdbeben Namen von Menschen siebentausend. Und die übrigen gerieten in Furcht und gaben Herrlichkeit dem Gott des Himmels.',
        14: 'Das zweite Wehe ist vergangen. Siehe, das dritte Wehe kommt schnell.',
        15: 'Und der siebente Engel posaunte, und es wurden große Stimmen im Himmel, die sprachen: Die Reiche der Welt sind unseres Herrn und seines Christus geworden, und Er wird regieren in die Zeitläufe der Zeitläufe.',
        16: 'Und die vierundzwanzig Ältesten, die vor Gott auf ihren Thronen saßen, fielen auf ihre Angesichte und beteten Gott an,',
        17: 'Und sagten: Wir danken Dir, Herr, Gott, Allmächtiger, Der da ist, und Der da war, und Der da kommt, daß Du Deine große Kraft an Dich genommen und Dein Reich angetreten hast.',
        18: 'Und die Völkerschaften zürnten, und gekommen ist Dein Zorn und die Zeit der Toten, zu richten und den Lohn zu geben Deinen Knechten, den Prophe- ten und den Heiligen, und denen, die Deinen Namen fürchten, den Kleinen und den Großen und zu verderben, welche die Erde verderben.',
        19: 'Und der Tempel Gottes ward aufgetan im Himmel, und ward gesehen Seine Bundeslade in Seinem Tempel; und es geschahen Blitze und Stimmen und Donner und Erdbeben und großer Hagel.',
    },
    12: {
        1: 'Und ein großes Zeichen erschien am Himmel: ein Weib, von der Sonne umkleidet, und der Mond unter ihren Füßen, und auf ihrem Haupte eine Krone von zwölf Sternen.',
        2: 'Und sie war schwanger, schrie in Wehen und quälte sich, zu gebären.',
        3: 'Und ein anderes Zeichen ward im Himmel gesehen, und siehe, ein großer, feuerroter Drache, der hatte sieben Häupter und zehn Hörner und auf seinen Häuptern sieben Diademe.',
        4: 'Und sein Schwanz zog den dritten Teil der Sterne des Himmels nach sich und warf sie auf die Erde. Und der Drache stand vor dem Weib, da sie gebären wollte, um ihr Kind, wenn sie geboren hätte, aufzufressen.',
        5: 'Und sie gebar ein Männliches, einen Sohn, der alle die Völkerschaften mit eisernem Stabe weiden sollte; und ihr Kind ward entrückt zu Gott und Seinem Thron.',
        6: 'Und das Weib floh in die Wüste, wo sie einen Ort hat, der von Gott bereitet worden, auf daß man sie allda tausendzweihundertsechzig Tage ernährete.',
        7: 'Und es ward Krieg in dem Himmel; Michael und seine Engel führten Krieg mit dem Drachen, und der Drache führte Krieg und seine Engel.',
        8: 'Und sie vermochten es nicht, und ward ihre Stätte im Himmel nicht mehr gefunden.',
        9: 'Und der große Drache, die alte Schlange, die da heißt Teufel und Satan, der den ganzen Erdkreis irreführte, wurde auf die Erde geworfen, und mit ihm wurden seine Engel ausgeworfen.',
        10: 'Und ich hörte eine große Stimme im Himmel, die sagte: Nun ist das Heil und die Kraft und das Reich unseres Gottes und die Gewalt Seines Christus geworden. Denn hinabgeworfen ist der Verkläger unserer Brüder, der Tag und Nacht sie vor unserem Gott verklagte.',
        11: 'Und sie haben ihn überwunden durch das Blut des Lammes, und durch das Wort ihres Zeugnisses, und ihre Seele nicht geliebt bis in den Tod.',
        12: 'Darum seid fröhlich, ihr Himmel und die darin wohnen. Wehe den Bewohnern der Erde und des Meeres, daß zu euch hinabstieg der Teufel, und hat einen großen Grimm, da er weiß, daß er wenig Zeit hat.',
        13: 'Und da der Drache sah, daß er auf die Erde geworfen war, verfolgte er das Weib, das den Sohn geboren hatte.',
        14: 'Und dem Weibe wurden zwei Flügel des großen Adlers gegeben, auf daß sie in die Wüste flöge an ihren Ort, um daselbst ernährt zu werden vor dem Angesicht der Schlange eine Zeit und Zeiten und eine halbe Zeit.',
        15: 'Und die Schlange warf aus hinter dem Weibe her Wasser aus ihrem Munde, wie einen Strom, um sie im Strome fortzuschwemmen.',
        16: 'Und die Erde half dem Weibe; und die Erde tat ihren Mund auf und verschlang den Strom, den der Drache aus seinem Munde auswarf.',
        17: 'Und der Drache ward zornig über das Weib, und ging hin, Krieg zu führen mit den übrigen von ihrem Samen, welche die Gebote Gottes halten und das Zeugnis von Jesus Christus haben.',
    },
    13: {
        1: 'Und ich stand auf den Sand des Meeres und sah aus dem Meer ein Tier aufsteigen, das hatte sieben Häupter und zehn Hörner, und auf seinen Hörnern zehn Diademe, und auf seinen Häuptern Namen der Lästerung.',
        2: 'Und das Tier, das ich sah, glich einem Pardel, und seine Füße waren wie die eines Bären, und sein Maul wie eines Löwen Maul. Und der Drache gab ihm seine Kraft und seinen Thron und große Gewalt.',
        3: 'Und ich sah eines seiner Häupter wie auf den Tod verwundet, und die Todeswunde ward geheilt. Und die ganze Erde wunderte sich hinter dem Tiere her.',
        4: 'Und sie beteten den Drachen an, der dem Tier die Gewalt gab, und das Tier beteten sie an und sprachen: Wer ist dem Tier gleich? Und wer kann mit ihm Krieg führen?',
        5: 'Und es ward ihm ein Maul gegeben, große Dinge zu reden und Lästerungen, und die Gewalt gegeben, zweiundvierzig Monate so zu tun.',
        6: 'Und es tat sein Maul auf zur Lästerung wider Gott, zu lästern Seinen Namen und Seine Hütte und die im Himmel wohnen.',
        7: 'Und es ward ihm gegeben, mit den Heiligen Krieg zu führen und sie zu überwinden, und ihm Gewalt gegeben über jeglichen Stamm und jede Zunge und Völkerschaft.',
        8: 'Und es werden es anbeten alle, die auf Erden wohnen, deren Name nicht im Buch des Lebens des Lammes geschrieben ist, das erschlagen worden seit der Gründung der Welt.',
        9: 'Hat jemand ein Ohr, der höre.',
        10: 'Wer in Gefangenschaft führt, der geht in Gefangenschaft hin, so jemand mit dem Schwert tötet, der muß mit dem Schwert getötet werden. Hier ist die Geduld und der Glaube der Heiligen.',
        11: 'Und ich sah ein anderes Tier aus der Erde aufsteigen; und es hatte zwei Hörner, wie ein Lamm, und redete wie ein Drache.',
        12: 'Und es tut alle die Gewalt des ersten Tieres vor ihm und macht, daß die Erde, und die auf ihr wohnen, das erste Tier anbeten, dessen Todeswunde geheilt worden war.',
        13: 'Und es tut große Zeichen, so daß es vor den Menschen auch Feuer vom Himmel auf die Erde fallen läßt;',
        14: 'Und führt irre, die auf Erden wohnen, durch die Zeichen, die ihm gegeben wurden vor dem Tiere zu tun, und sagt denen, die auf Erden wohnen, sie sollten dem Tiere, das die Wunde vom Schwert hatte und lebte, ein Bild machen.',
        15: 'Und es ward ihm gegeben, dem Bilde des Tieres Geist zu geben, so daß das Bild des Tieres auch redet, und macht, daß die, so das Bild des Tieres nicht anbeten, getötet werden;',
        16: 'Und macht, daß es allen, den Kleinen und den Großen, und den Reichen und den Armen, und den Freien und den Knechten ein Malzeichen auf ihre rechte Hand oder auf ihre Stirnen gibt;',
        17: 'Und daß keiner kaufen oder verkaufen kann, wenn er nicht das Malzeichen oder den Namen des Tieres oder die Zahl seines Namens hat.',
        18: 'Hier ist die Weisheit. Wer Verständnis hat, berechne die Zahl des Tieres, denn es ist eines Menschen Zahl und seine Zahl ist sechshundertsechsundsechzig.',
    },
    14: {
        1: 'Und ich sah, und siehe! Das Lamm stand auf dem Berge Zion und mit ihm hundertvierundvierzigtausend, die den Namen Seines Vaters an ihren Stirnen geschrieben hatten.',
        2: 'Und ich hörte eine Stimme aus dem Himmel, wie die Stimme vieler Wasser, und wie die Stimme eines großen Donners. Und die Stimme, die ich hörte, war wie von Harfenspielern, die auf ihren Harfen spielen.',
        3: 'Und sie sangen als wie ein neues Lied vor dem Thron und vor den vier Tieren und den Ältesten, und niemand konnte das Lied lernen, als die hundertvierundvierzigtausend, die erkauft sind von der Erde.',
        4: 'Diese sind es, die sich nicht mit Weibern befleckt haben; denn Jungfrauen sind sie. Diese sind es, die dem Lamm nachfolgen, wo es hingeht. Diese sind aus den Menschen als Erstlinge Gott und dem Lamme erkauft.',
        5: 'Und in ihrem Munde ward kein Trug erfunden; denn sie sind tadellos vor dem Throne Gottes.',
        6: 'Und ich sah einen anderen Engel mitten durch den Himmel fliegen, der ein ewiges Evangelium hatte, zu verkündigen denen, die auf der Erde wohnen, und jeder Völkerschaft, und Stamm, und Zunge, und Volk.',
        7: 'Und sagte mit großer Stimme: Fürchtet Gott, und gebet Ihm Herrlichkeit, daß die Stunde Seines Gerichts gekommen ist, und betet Ihn an, Der den Himmel und die Erde und das Meer und die Quellen der Wasser geschaffen hat.',
        8: 'Und ein anderer Engel folgte nach, der sprach: Gefallen, gefallen ist Babylon, die große Stadt! weil sie aus dem Wein ihres Grimmes ihrer Buhlerei alle Völkerschaften getränkt hat.',
        9: 'Und ihnen folgte ein dritter Engel nach, und sprach mit großer Stimme: So jemand das Tier anbetet und sein Bild, und ein Malzeichen nimmt auf seine Stirne oder auf seine Hand,',
        10: 'Soll auch er trinken vom Wein des Grimmes Gottes, der lauter eingeschenkt ist im Kelche Seines Zorns, und soll mit Feuer und Schwefel gequält werden vor den heiligen Engeln und vor dem Lamme.',
        11: 'Und der Rauch ihrer Qual steigt auf in die Zeitläufe der Zeitläufe, und keine Ruhe haben Tag und Nacht die, so das Tier anbeten und sein Bild, und so jemand das Malzeichen seines Namens annimmt.',
        12: 'Hier ist die Geduld der Heiligen, hier sind die, so Gottes Gebote halten und den Glauben an Jesus.',
        13: 'Und ich hörte eine Stimme aus dem Himmel zu mir sagen: Schreibe: Selig sind die Toten, die in dem Herrn sterben, von nun an! Ja, spricht der Geist, auf daß sie ruhen von ihren Mühsalen. Ihre Werke aber folgen mit ihnen nach.',
        14: 'Und ich sah, und siehe, eine weiße Wolke, und auf der Wolke saß einer, der dem Menschensohne glich, der hatte eine goldene Krone auf dem Haupt und eine scharfe Sichel in seiner Hand.',
        15: 'Und ein anderer Engel kam aus dem Tempel heraus und schrie mit großer Stimme dem zu, der auf der Wolke saß: Lege deine Sichel an und ernte; denn die Stunde für die Ernte ist gekommen, weil die Ernte der Erde ist dürre geworden.',
        16: 'Und der auf der Wolke saß, schlug mit seiner Sichel an die Erde an, und die Erde ward geerntet.',
        17: 'Und ein anderer Engel kam heraus aus dem Tempel im Himmel, und auch er hatte eine scharfe Sichel.',
        18: 'Und ein anderer Engel ging aus dem Altar hervor, der hatte Gewalt über das Feuer, und rief dem, der die scharfe Sichel hatte, mit großem Geschrei und sprach: Lege deine scharfe Sichel an und lies die Trauben des Weinstocks der Erde; denn seine Beeren sind reif geworden.',
        19: 'Und der Engel schlug seine Sichel an die Erde und las den Weinstock der Erde und warf es in die große Kelter des Grimmes Gottes.',
        20: 'Und getreten ward die Kelter außerhalb der Stadt; und es kam Blut heraus aus der Kelter bis an die Zügel der Pferde, auf tausendsechshundert Stadien.',
    },
    15: {
        1: 'Und ich sah ein anderes Zeichen im Himmel, groß und wunderbar, sieben Engel, welche die sieben letzten Plagen hatten; denn in ihnen ist der Grimm Gottes vollendet.',
        2: 'Und ich sah wie ein gläsern Meer mit Feuer vermischt, und die so siegten über das Tier und über sein Bild und über sein Malzeichen, und über die Zahl seines Namens, standen am gläsernen Meer und hatten Harfen Gottes,',
        3: 'Und sangen das Lied Moses, des Knechtes Gottes, und das Lied des Lammes und sprachen: Groß und wunderbar sind Deine Werke, Herr, Gott, Allmächtiger! gerecht und wahrhaftig Deine Wege, Du König der Heiligen!',
        4: 'Wer sollte Dich nicht fürchten, Herr, und Deinen Namen verherrlichen? Denn Du allein bist heilig. Denn alle Völkerschaften werden kommen und vor Dir anbeten; denn Deine Urteile sind offenbar geworden.',
        5: 'Und nach dem sah ich, und siehe, es ward aufgetan der Tempel der Hütte des Zeugnisses im Himmel,',
        6: 'Und heraus kamen die sieben Engel, welche die sieben Plagen hatten, aus dem Tempel, angetan mit reiner, glänzender Leinwand, und umgürtet um die Brust mit goldenen Gürteln.',
        7: 'Und eines von den vier Tieren gab den sieben Engeln sieben goldene Schalen voll vom Grimme des Gottes, Der da lebt in die Zeitläufe der Zeitläufe.',
        8: 'Und der Tempel ward des Rauches voll von der Herrlichkeit Gottes und von Seiner Kraft, und niemand konnte in den Tempel eingehen, bis daß die sieben Plagen der sieben Engel vollendet waren.',
    },
    16: {
        1: 'Und ich hörte eine große Stimme aus dem Tempel zu den sieben Engeln sagen: Gehet hin und gießet die Schalen des Grimmes Gottes auf die Erde aus!',
        2: 'Und der erste ging hin und goß seine Schale auf die Erde aus, und es ward böses und arges Geschwür an den Menschen, die das Malzeichen des Tieres hatten und sein Bild anbeteten.',
        3: 'Und der zweite Engel goß seine Schale in das Meer aus; und es ward Blut wie eines Toten, und alle lebendige Seele starb in dem Meere.',
        4: 'Und der dritte Engel goß seine Schale in die Flüsse und in die Quellen der Wasser aus, und sie wurden Blut.',
        5: 'Und ich hörte den Engel der Wasser sagen: O Herr, gerecht bist Du, Der da ist und Der da war, und der Heilige, daß Du solches gerichtet hast.',
        6: 'Denn sie haben das Blut der Heiligen und der Propheten vergossen, und Du gabst ihnen Blut zu trinken; denn sie sind es wert.',
        7: 'Und ich hörte einen anderen aus dem Altar sagen: Ja, Herr, Gott, Allmächtiger! Wahrhaftig und gerecht sind Deine Gerichte!',
        8: 'Und der vierte Engel goß seine Schale aus auf die Sonne; und es ward ihm gegeben, die Menschen mit Hitze zu schlagen durch Feuer.',
        9: 'Und die Menschen entbrannten mit großer Hitze und lästerten den Namen Gottes, Der Gewalt über diese Plagen hat, und sie taten nicht Buße, Ihm die Herrlichkeit zu geben.',
        10: 'Und es goß der fünfte Engel seine Schale auf den Thron des Tieres aus; und sein Reich ward verfinstert, und sie zerbissen vor Schmerz ihre Zungen,',
        11: 'Und lästerten den Gott des Himmels ob ihren Schmerzen und ob ihren Geschwüren, und taten nicht Buße von ihren Werken.',
        12: 'Und der sechste Engel goß seine Schale auf den großen Strom Euphrat aus, und sein Wasser vertrocknete, auf daß der Weg der Könige vom Aufgang der Sonne bereitet würde.',
        13: 'Und ich sah aus dem Munde des Drachen, und aus dem Munde des Tieres und aus dem Munde des falschen Propheten drei unreine Geister, ähnlich Fröschen.',
        14: 'Denn sie sind die Geister von Dämonen, welche Zeichen tun, welche ausgehen zu den Königen des Landes und des ganzen Erdkreises, sie zu versammeln zum Kriege auf jenen großen Tag Gottes, des Allmächtigen!',
        15: 'Siehe, Ich komme wie ein Dieb! Selig, wer da wacht und seine Kleider hält, daß er nicht nackend wandle, und man seine Blöße sehe.',
        16: 'Und sie versammelten sie an den Ort, der heißt auf hebräisch Harmageddon.',
        17: 'Und der siebente Engel goß seine Schale in die Luft aus. Und es ging eine große Stimme von dem Tempel des Himmels, vom Throne aus und sprach: Es ist geschehen!',
        18: 'Und es geschahen Blitze und Stimmen und Donner, und ein so großes Erdbeben, desgleichen nicht gewesen ist, seit Menschen geworden auf Erden, ein solches Erdbeben also groß.',
        19: 'Und die große Stadt wurde zu drei Teilen, und es fielen die Städte der Völkerschaften. Und Babylon, der großen, ward gedacht vor Gott, ihr zu geben den Kelch des Weins des Grimmes Seines Zorns.',
        20: 'Und jegliche Insel floh, und Berge wurden nicht mehr gefunden.',
        21: 'Und großer Hagel, wie zentnerschwer, fiel aus dem Himmel auf die Menschen. Und die Menschen lästerten Gott ob der Plage des Hagels, weil sehr groß war seine Plage.',
    },
    17: {
        1: 'Und es kam einer der sieben Engel, welche die sieben Schalen hatten, und redete mit mir und sagte: Komm her, ich will dir das Gericht der großen Buhlerin zeigen, die auf den vielen Wassern sitzt.',
        2: 'Mit welcher haben gebuhlt die Könige der Erde, und es sind von dem Wein ihrer Buhlerei trunken worden die, so die Erde bewohnen.',
        3: 'Und er brachte mich im Geist weg in eine Wüste; und ich sah ein Weib auf einem scharlachroten Tiere sitzen, das voll von Namen der Lästerung war und sieben Häupter und zehn Hörner hatte.',
        4: 'Und das Weib war mit Purpur und Scharlach umkleidet, und übergoldet mit Gold und kostbaren Steinen und Perlen; sie hatte einen goldenen Becher in ihrer Hand, der voll von Greueln und Unreinheit ihrer Buhlerei war.',
        5: 'Und auf ihrer Stirne war ein Name geschrieben: Geheimnis! Babylon, die große, die Mutter der Buhlereien und der Greuel der Erde.',
        6: 'Und ich sah das Weib trunken vom Blute der Heiligen und vom Blute der Zeugen Jesu. Und da ich sie sah, verwunderte ich mich mit großer Verwunderung.',
        7: 'Und der Engel sprach zu mir: Warum verwunderst du dich? Ich will dir sagen das Geheimnis des Weibes und des Tieres, das sie trägt, das die sieben Häupter und die zehn Hörner hat.',
        8: 'Das Tier, das du gesehen hast, war, und ist nicht, und wird aus dem Abgrund heraufsteigen und ins Verderben fortgehen. Und verwundern werden sich, die auf der Erde wohnen, deren Namen nicht geschrieben sind im Buche des Lebens von Gründung der Welt an, wenn sie das Tier sehen, das war und nicht ist und dennoch ist.',
        9: 'Hier ist der Sinn, der Weisheit hat; die sieben Häupter sind sieben Berge, worauf das Weib sitzt; und sind sieben Könige,',
        10: 'Die fünfe sind gefallen, und der eine ist, der andere ist noch nicht gekommen, und wenn er kommt, muß er ein wenig bleiben.',
        11: 'Und das Tier, das war und nicht ist, ist auch selbst der achte, und ist von den sieben und geht hin ins Verderben.',
        12: 'Und die zehn Hörner, die Du gesehen, sind zehn Könige, welche das Reich noch nicht empfangen haben, sondern Gewalt wie Könige eine Stunde empfangen mit dem Tier.',
        13: 'Diese haben eine Meinung, und übergeben dem Tiere ihre Kraft und Gewalt.',
        14: 'Diese werden mit dem Lamme kriegen, und das Lamm wird sie überwinden, denn es ist der Herr der Herren und der König der Könige; und die mit Ihm sind Berufene und Auserwählte und Getreue.',
        15: 'Und er spricht zu mir: Die Wasser, die du gesehen, wo die Buhlerin sitzt, sind Völker und Volksmengen und Völkerschaften und Zungen.',
        16: 'Und die zehn Hörner, die du gesehen auf dem Tiere, diese werden die Buhlerin hassen, und werden sie wüste machen und bloß, und ihr Fleisch essen und sie mit Feuer verbrennen.',
        17: 'Denn Gott hat es in ihre Herzen gegeben, Seine Meinung zu tun, und zu tun eine Meinung, und ihr Reich dem Tiere zu geben, bis vollendet werden die Reden Gottes.',
        18: 'Und das Weib, das du gesehen, ist die große Stadt, welche das Reich hat über die Könige der Erde.',
    },
    18: {
        1: 'Und nach diesem sah ich einen anderen Engel aus dem Himmel herabsteigen, der hatte große Gewalt, und die Erde ward erleuchtet von seiner Herrlichkeit.',
        2: 'Und er rief in Stärke, mit großer Stimme und sprach: Gefallen, gefallen ist Babylon, die große! und ein Wohnplatz von Dämonen, und ein Gefängnis jedes unreinen Geistes, und ein Gefängnis jedes unreinen und verhaßten Vogels geworden.',
        3: 'Denn von dem Weine des Grimmes ihrer Buhlerei haben alle Völkerschaften getrunken, und die Könige der Erde haben mit ihr gebuhlt, und die Kaufleute der Erde sind von der Kraft ihrer Üppigkeit reich geworden.',
        4: 'Und ich hörte eine andere Stimme aus dem Himmel sprechen: Gehet aus von ihr, Mein Volk, auf daß ihr nicht teilhabet an ihren Sünden, und daß ihr nicht von ihren Plagen empfanget.',
        5: 'Denn ihre Sünden reichten bis an den Himmel, und ihrer Ungerechtigkeiten hat Gott gedacht.',
        6: 'Vergeltet ihr, wie auch sie euch vergalt. Und verdoppelt ihr das Doppelte nach ihren Werken; mischt in dem Kelche, in dem sie gemischt, ihr das Doppelte!',
        7: 'Wieviel sie sich verherrlichte und schwelgte, so viel gebt ihr Qual und Trauer; weil sie in ihrem Herzen sprach: Ich sitze als Königin, und Witwe bin ich nicht, und Trauer werde ich nicht sehen!',
        8: 'Darum an einem Tage sollen ihre Plagen kommen, Tod und Trauer und Hungersnot! und im Feuer soll sie verbrannt werden; denn stark ist der Herr, Gott, Der sie richtet!',
        9: 'Und weinen werden und jammern über sie die Könige der Erde, die mit ihr gebuhlt und geschwelgt, wenn sie den Rauch von ihrem Brande erblicken.',
        10: 'Sie werden ferne stehen aus Furcht vor ihrer Qual, und sagen: Wehe, wehe, die große Stadt Babylon, die starke Stadt! Denn in einer Stunde ist dein Gericht gekommen!',
        11: 'Und die Kaufleute der Erde weinen und trauern über sie, weil niemand mehr ihre Ware kauft:',
        12: 'Die Ware von Gold und Silber und kostbarem Stein und Perlen und Byssus und Purpur und Seide und Scharlach, und alles Thynenholz, und alles Geräte von Elfenbein, und alles Geräte von kostbarstem Holze, und von Erz, und von Eisen, und von Marmor;',
        13: 'Und Zimt und Räuchwerk, und Salbe und Weihrauch, und Wein und Öl, und Semmelmehl und Weizen, und Rinder und Schafe, und Rosse und Wagen, und Leiber und Seelen von Menschen.',
        14: 'Und das Obst, deiner Seele Begehr, ist von dir weggegangen, und alles Fette und Glänzende ist von dir weggegangen, und du wirst es nicht mehr finden.',
        15: 'Und deren Kaufleute, die von ihr reich geworden, werden von ferne stehen aus Furcht vor ihrer Qual, weinen und klagen,',
        16: 'Und sagen: Wehe! Wehe! Die große Stadt, die sich mit Byssus und Purpur und Scharlach umkleidete, und mit Gold sich übergoldete und mit kostbarem Steine und Perlen!',
        17: 'Denn in einer Stunde ist solcher Reichtum verwüstet! Und alle Steuerleute, und all die Gesellschaft auf den Schiffen, und die Schiffsleute und alle, die auf dem Meere ihr Werk haben, standen von weitem,',
        18: 'Und schrien, da sie den Rauch ihres Brandes sahen, und sprachen: Wer war gleich dieser großen Stadt!',
        19: 'Und sie warfen Staub auf ihre Häupter und schrien weinend und trauernd: Wehe! Wehe! Die große Stadt, in der alle, die Schiffe auf dem Meere hatten, von deren Kostbarkeit reich geworden sind! Denn in einer Stunde ist sie wüste geworden!',
        20: 'Seid fröhlich über sie, du Himmel, und ihr heiligen Apostel und Propheten; denn Gott hat gerichtet über sie für euch das Gericht!',
        21: 'Und ein starker Engel hob auf einen Stein wie ein großer Mühlstein, und warf ihn in das Meer und sprach: So wird mit Ungestüm die große Stadt Babylon hinabgeworfen, und nimmermehr gefunden werden.',
        22: 'Und die Stimme der Harfenspieler und Sänger und der Flötenspieler und Posaunenbläser wird nicht mehr in dir gehört! Und kein Künstler irgendeiner Kunst wird mehr in dir gefunden, und die Stimme der Mühle in dir nicht mehr gehört.',
        23: 'Und kein Licht der Lampe leuchte mehr in dir! Und nimmer soll in dir die Stimme eines Bräutigams und einer Braut gehört werden! Denn deine Kaufleute waren die Großen der Erde; denn alle Völkerschaften wurden durch deine Zauberei irregeführt;',
        24: 'Und in ihr wurde das Blut der Propheten und Heiligen und aller Erschlagenen auf Erden gefunden.',
    },
    19: {
        1: 'Nach diesem hörte ich wie eine große Stimme einer großen Volksmenge in dem Himmel sagen: Hallelujah! Das Heil und die Herrlichkeit, und die Ehre und die Kraft dem Herrn, unserem Gotte!',
        2: 'Denn wahrhaftig und gerecht sind Seine Gerichte! Denn Er hat die große Buhlerin gerichtet, welche die Erde mit ihrer Buhlerei verdarb, und gerächt das Blut Seiner Knechte von ihrer Hand.',
        3: 'Und sie sprachen zum zweitenmal: Hallelujah! Und ihr Rauch steigt auf in die Zeitläufe der Zeitläufe.',
        4: 'Und die vierundzwanzig Ältesten und die vier Tiere fielen nieder und beteten an Gott, Der auf dem Throne saß, und sprachen: Amen. Hallelujah!',
        5: 'Und vom Thron ging aus eine Stimme und sagte: Lobet unseren Gott, alle Seine Knechte und die Ihn fürchten, die Kleinen und die Großen!',
        6: 'Und ich hörte, wie eine Stimme einer großen Volksmenge und wie die Stimme vieler Wasser und wie die Stimme starker Donner sagen: Hallelujah! denn der Herr, Gott, der Allmächtige, regiert!',
        7: 'Lasset uns freuen und frohlocken und Ihm die Herrlichkeit geben; denn die Hochzeit des Lammes ist gekommen, und Sein Weib hat Sich bereitet.',
        8: 'Und ihr ward gegeben, sich zu umkleiden mit reinem und glänzendem Byssus denn der Byssus ist die Gerechtigkeit der Heiligen.',
        9: 'Und er sagte mir: Schreibe: Selig sind, die zum Hochzeitsmahl des Lammes berufen sind. Und er sagte mir: Dies sind die wahrhaftigen Worte Gottes!',
        10: 'Und ich fiel hin vor seinen Füßen, ihn anzubeten. Und er sagte mir: Siehe zu, tue das nicht! Ich bin dein und deiner Brüder Mitknecht, die ihr Jesu Zeugnis habt. Gott bete an!',
        11: 'Und ich sah den Himmel aufgetan, und siehe, ein weißes Roß, und Der darauf saß, heißt Treu und Wahrhaftig, und richtet und krieget mit Gerechtigkeit.',
        12: 'Und Seine Augen sind wie eine Feuerflamme, und auf Seinem Haupte viele Diademe. Er hatte einen Namen geschrieben, den niemand weiß, außer Ihm;',
        13: 'Und Er war umkleidet mit einem Kleid, in Blut getaucht, und Sein Name heißt: Das Wort Gottes.',
        14: 'Und die Heere im Himmel folgten Ihm nach auf weißen Rossen, mit weißem und reinem Byssus angetan;',
        15: 'Und aus Seinem Munde geht aus ein scharfes Schlachtschwert, auf daß Er die Völkerschaften damit schlage, und Er wird sie mit eisernem Stabe weiden, und Er Selbst tritt die Kelter des Grimms und des Zornes Gottes, des Allmächtigen.',
        16: 'Und Er hat auf Seinem Kleid und auf Seiner Hüfte einen Namen geschrieben: König der Könige und Herr der Herren.',
        17: 'Und ich sah einen Engel in der Sonne stehen, und er schrie mit großer Stimme und sprach zu allen Vögeln, die mitten am Himmel fliegen: Kommet her und versammelt euch zum großen Mahle Gottes.',
        18: 'Auf daß ihr esset Fleisch der Könige, und Fleisch der Kriegsobersten, und Fleisch der Starken, und Fleisch der Rosse und derer, die darauf sitzen, und Fleisch aller Freien und Knechte, und der Kleinen und der Großen.',
        19: 'Und ich sah das Tier und die Könige der Erde und ihre Heere versammelt, Krieg zu führen mit dem, Der auf dem Rosse saß, und mit Seinem Heer.',
        20: 'Und es ward gegriffen das Tier und mit ihm der falsche Prophet, der die Zeichen vor ihm tat, womit er die irreführte, die das Malzeichen des Tieres angenommen, und die sein Bild anbeteten. Lebendig wurden diese beide in den See des Feuers geworfen, der mit Schwefel brennt.',
        21: 'Und die übrigen wurden getötet mit dem Schlachtschwerte des auf dem Rosse Sitzenden, das aus Seinem Munde ausging. Und alle Vögel wurden gesättigt von ihrem Fleisch.',
    },
    20: {
        1: 'Und ich sah einen Engel aus dem Himmel herabsteigen, der hatte den Schlüssel des Abgrundes und eine große Kette auf seiner Hand.',
        2: 'Und er griff den Drachen, die alte Schlange, welche ist der Teufel und der Satan, und band ihn tausend Jahre;',
        3: 'Und warf ihn in den Abgrund und verschloß ihn und versiegelte über ihm, damit er die Völkerschaften nicht weiter irreführte, bis die tausend Jahre vollendet wären, und danach muß er auf eine kleine Zeit gelöst werden.',
        4: 'Und ich sah Throne, und sie setzten sich darauf, und es ward ihnen gegeben das Gericht und die Seelen derer, die um des Zeugnisses Jesu und des Wortes Gottes willen unter dem Beile fielen, und die das Tier und sein Bild nicht angebetet, noch das Malzeichen an ihre Stirn und auf ihre Hand angenommen; und sie lebten und regierten mit Christus die tausend Jahre.',
        5: 'Die übrigen aber von den Toten lebten nicht auf, bis daß die tausend Jahre vollendet wären. Dies ist die erste Auferstehung.',
        6: 'Selig und heilig ist, wer teilhat an der ersten Auferstehung. Über diese hat der zweite Tod keine Gewalt! Sondern sie sollen Priester Gottes und des Christus sein, und mit Ihm regieren tausend Jahre.',
        7: 'Und wenn die tausend Jahre vollendet sind, wird der Satan aus seinem Gefängnis gelöst werden;',
        8: 'Und wird ausgehen irrezuführen die Völkerschaften in den vier Ecken der Erde, den Gog und den Magog, sie zum Kriege zu versammeln, deren Zahl ist wie der Sand am Meere.',
        9: 'Und sie zogen herauf über die Breite der Erde und umringten das Lager der Heiligen und die geliebte Stadt. Und es kam Feuer von Gott aus dem Himmel herab und verzehrte sie.',
        10: 'Und der Teufel, der sie irreführte, ward in den See von Feuer und Schwefel geworfen, wo auch das Tier und der Lügenprophet sind, und sie werden Tag und Nacht gequält werden in die Zeitläufe der Zeitläufe.',
        11: 'Und ich sah einen weißen, großen Thron, und Den, Der darauf saß, vor Dessen Angesicht die Erde und der Himmel flohen; und keine Stätte ward für sie gefunden.',
        12: 'Und ich sah die Toten, kleine und große, vor Gott stehen, und Bücher wurden aufgetan; und ein anderes Buch ward aufgetan, welches das des Lebens ist; und die Toten wurden gerichtet aus dem, was in den Büchern geschrieben war, nach ihren Werken.',
        13: 'Und das Meer gab die Toten, die in ihm waren, und der Tod und Hölle gaben die Toten, die in ihnen waren, und sie wurden gerichtet, jeder nach seinen Werken.',
        14: 'Und der Tod und die Hölle wurden in den See von Feuer geworfen. Dies ist der zweite Tod.',
        15: 'Und so jemand nicht gefunden ward geschrieben im Buche des Lebens, der ward geworfen in den See von Feuer.',
    },
    21: {
        1: 'Und ich sah einen neuen Himmel und eine neue Erde; denn der erste Himmel und die erste Erde waren vergangen und das Meer ist nicht mehr.',
        2: 'Und ich, Johannes, sah die heilige Stadt, das neue Jerusalem, von Gott aus dem Himmel herabsteigen, zubereitet wie eine Braut, für ihren Mann geschmückt.',
        3: 'Und ich hörte eine große Stimme aus dem Himmel sagen: Siehe, die Hütte Gottes bei den Menschen! Und Er wird bei ihnen wohnen, und sie werden Sein Volk sein, und Er Selbst wird bei ihnen sein, ihr Gott.',
        4: 'Und Gott wird abwischen jede Träne von ihren Augen, und der Tod wird nicht mehr sein, kein Trauern, kein Geschrei, keine Mühsal wird mehr sein; denn das Erste ist vergangen.',
        5: 'Und es sprach, Der auf dem Throne saß: Siehe, Ich mache alles neu. Und Er spricht zu mir: Schreibe, denn diese Worte sind wahrhaftig und getreu.',
        6: 'Und Er sprach zu mir: Es ist geschehen. Ich bin das Alpha und das Omega, der Anfang und das Ende. Ich werde dem Dürstenden geben aus dem Quell des Wassers des Lebens umsonst.',
        7: 'Wer überwindet, der soll alles ererben, und Ich werde ihm Gott sein, und er soll Mir Sohn sein.',
        8: 'Den Zaghaften aber und den Untreuen und den Greuelhaften, und den Mördern, und den Buhlern, und den Zauberern und Götzendienern, und allen Lügnern wird ihr Teil im See, der mit Feuer und Schwefel brennt, welcher ist der zweite Tod.',
        9: 'Und es kam zu mir einer der sieben Engel, welche die sieben Schalen voll der sieben letzten Plagen hatten, und redete mit mir und sagte: Komm, ich will die zeigen die Braut, des Lammes Weib.',
        10: 'Und er entrückte mich im Geist auf einen großen und hohen Berg und zeigte mir die große Stadt, das heilige Jerusalem, aus dem Himmel herabsteigen von Gott.',
        11: 'Sie hatte die Herrlichkeit Gottes, und Ihr Licht glich dem kostbarsten Steine, wie dem Stein Jaspis, der wie Kristall glänzt.',
        12: 'Und sie hatte eine große und hohe Mauer und hatte zwölf Tore und über den Toren zwölf Engel, und Namen darauf geschrieben, welche sind die der zwölf Stämme der Söhne Israels,',
        13: 'Von Aufgang drei Tore, von Mitternacht drei Tore, von Mittag drei Tore, von Niedergang drei Tore.',
        14: 'Und die Mauer der Stadt hatte zwölf Gründe und in diesen die Namen der zwölf Apostel des Lammes.',
        15: 'Und der mit mir redete, hatte ein goldenes Rohr, damit er die Stadt und ihre Tore und ihre Mauer messe.',
        16: 'Und die Stadt liegt viereckig; und ihre Länge ist so viel als auch die Breite. Und er maß die Stadt mit dem Rohr zu zwölftausend Stadien. Ihre Länge und Breite und Höhe sind gleich.',
        17: 'Und er maß ihre Mauer hundertvierundvierzig Ellen, das Maß eines Menschen, welches ist das eines Engels.',
        18: 'Und der Aufbau der Mauer war aus Jaspis und die Stadt reines Gold, ähnlich dem reinen Glas.',
        19: 'Und die Gründe der Mauer der Stadt waren mit allerlei kostbarem Gestein geschmückt; der erste Grund war ein Jaspis, der zweite ein Saphir, der dritte ein Chalzedon, der vierte ein Smaragd,',
        20: 'Der fünfte ein Sardonyx, der sechste ein Sarder, der siebente ein Chrysolith, der achte ein Beryll, der neunte ein Topas, der zehnte ein Chrysopras, der elfte ein Hyazinth, der zwölfte ein Amethyst;',
        21: 'Und die zwölf Tore zwölf Perlen. Ein jedes der Tore war aus einer Perle, und die Straße der Stadt reines Gold, wie durchscheinendes Glas.',
        22: 'Und einen Tempel sah ich nicht in ihr; denn der Herr, Gott der Allmächtige, ist ihr Tempel, und das Lamm.',
        23: 'Und die Stadt bedarf nicht der Sonne, noch des Mondes, daß sie in ihr scheinen; denn die Herrlichkeit Gottes hat sie erleuchtet, und ihre Leuchte ist das Lamm.',
        24: 'Und die Völkerschaften derer, die gerettet werden, werden in ihrem Lichte wandeln und die Könige der Erde ihre Herrlichkeit und Ehre in sie bringen.',
        25: 'Und ihre Tore werden nicht verschlossen werden des Tags denn Nacht wird da nicht sein.',
        26: 'Und sie werden die Herrlichkeit und die Ehre der Völkerschaften in sie bringen.',
        27: 'Und nicht wird in sie eingehen etwas Gemeines, und das da Greuel tut und Lüge; sondern die geschrieben sind im Lebensbuch des Lammes.',
    },
    22: {
        1: 'Und er zeigte mir einen reinen Strom von Lebenswasser, glänzend wie Kristall, ausgehend vom Throne Gottes und des Lammes.',
        2: 'Inmitten ihrer Straße und des Stroms hier und dort der Baum des Lebens, welcher zwölf Früchte trägt, jeden einzelnen Monat seine Frucht gebend, und die Blätter des Baumes sind zur Heilung der Völkerschaften.',
        3: 'Und nichts Verbanntes wird mehr sein; und der Thron Gottes und des Lammes wird in ihr sein und Seine Knechte werden Ihm dienen;',
        4: 'Und werden sehen Sein Angesicht, und Sein Name wird auf ihren Stirnen sein.',
        5: 'Und Nacht wird dort nicht sein, noch bedürfen sie einer Leuchte oder des Lichts der Sonne; denn der Herr Gott wird sie erleuchten, und sie werden regieren in die Zeitläufe der Zeitläufe.',
        6: 'Und er sprach zu mir: Diese Worte sind getreu und wahrhaftig. Und der Herr, der Gott der heiligen Propheten, hat Seinen Engel ausgesandt, Seinen Knechten zu zeigen, was schnell geschehen soll.',
        7: 'Und siehe: Ich komme schnell. Selig, wer hält die Worte der Weissagung dieses Buches.',
        8: 'Und ich, Johannes, sah das und hörte es, und als ich gehört und gesehen, fiel ich hin, anzubeten vor den Füßen des Engels, der mir dieses zeigte.',
        9: 'Und er spricht zu mir: Siehe zu, tue es nicht! Denn ich bin dein Mitknecht und der deiner Brüder, der Propheten, und derer, welche die Worte dieses Buches halten. Gott bete an!',
        10: 'Und er spricht zu mir: Versiegle nicht die Worte der Weissagung dieses Buchs; denn die Zeit ist nahe.',
        11: 'Wer ungerecht ist, werde ferner ungerecht, und der Unreine werde ferner unrein. Und der Gerechte werde ferner gerecht, und der Heilige ferner heilig.',
        12: 'Und siehe, Ich komme schnell und Mein Lohn mit Mir, um jedem zu vergelten, wie sein Werk sein wird.',
        13: 'Ich bin das Alpha und das Omega, der Anfang und das Ende, der Erste und der Letzte.',
        14: 'Selig sind, die Seine Gebote tun, auf daß ihre Macht sei am Baume des Lebens, und sie durch die Tore eingehen in die Stadt.',
        15: 'Draußen aber sind die Hunde, und die Zauberer und die Buhler, und die Mörder und die Götzendiener und jeder, der die Lüge liebt und tut.',
        16: 'Ich, Jesus, habe Meinen Engel gesandt, euch dies an die Gemeinden zu bezeugen. Ich bin die Wurzel und das Geschlecht Davids, der glänzende Morgenstern.',
        17: 'Und der Geist und die Braut sagen: Komm! Und wer es hört, der spreche: Komm! Und wen dürstet, der komme, und wer es will, der nehme das Wasser des Lebens umsonst!',
        18: 'Denn Ich bezeuge jedem, der die Worte der Weissagung dieses Buches hört: So jemand zu demselben hinzusetzt, so wird Gott auf ihn legen die Plagen, die in diesem Buche geschrieben sind.',
        19: 'Und wenn jemand wegnimmt von den Worten des Buches dieser Weissagung, so wird Gott wegnehmen sein Teil vom Buche des Lebens, und von der heiligen Stadt, und von dem, was in diesem Buche geschrieben ist.',
        20: 'Es spricht, Der solches zeuget: Ja, Ich komme schnell, Amen! Ja, komm, Herr Jesus!',
        21: 'Die Gnade unseres Herrn Jesus Christus sei mit euch allen! Amen.',
    },
}
